CREATE TABLE actor_film (
  actor_id INTEGER NOT NULL REFERENCES actor(id) ON DELETE CASCADE,
  film_id  INTEGER NOT NULL REFERENCES film(id)  ON DELETE CASCADE,
  PRIMARY KEY (actor_id, film_id));

-- Reverse-direction index on (film_id, actor_id) covers lookups by film_id;
-- the primary key covers lookups by actor_id.

-- Owner writes links:
INSERT INTO actor_film (actor_id, film_id) VALUES (?, ?);
DELETE FROM actor_film WHERE actor_id = ? AND film_id = ?;

-- Reader loads the collection in one query:
SELECT film.* FROM actor_film
  JOIN film ON film.id = film_id
 WHERE actor_id = ?;
